result = Customers.WHERE(
    COUNT(transactions_made) >= 2
).CALCULATE(
    # Extract lastname from the full name (assuming last word is lastname)
    customer_lastname = name.split(' ')[-1],
    # Calculate success rate
    success_rate = SUM(transactions_made.CALCULATE(
        is_success = IFF(LOWER(status) == 'success', 1, 0)
    ).is_success) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

customer_success_rates = Customers.WHERE(
    COUNT(transactions_made) >= 2
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(LOWER(status) == 'success')) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

result = Customers.WHERE(
    join_date >= "1888-01-01"
).PARTITION(
    name="countries", 
    by=(country,)
).CALCULATE(
    count=COUNT(Customers)
)
